1	#!/usr/bin/env bun
2	/**
3	 * Exec agent
4	 *
5	 * Notes are the top-level intake records.
6	 * Triage turns notes into child tasks.
7	 * The scheduler executes runnable child tasks with project serialization.
8	 */
9	
10	import { query } from "@anthropic-ai/claude-agent-sdk";
11	import type {
12	  SDKAssistantMessage,
13	  SDKResultMessage,
14	} from "@anthropic-ai/claude-agent-sdk";
15	import { init, id } from "@instantdb/admin";
16	import schema from "../instant.schema";
17	import { readFileSync, writeFileSync, existsSync, unlinkSync } from "fs";
18	import { homedir } from "os";
19	import { resolve } from "path";
20	import { NOTE_STATUSES, TASK_STATUSES, SUMMARY_PLACEHOLDER } from "../lib/workflow";
21	import { triageTranscript } from "./triage";
22	import { getProjectPath, getProjectsRoot } from "./project-index";
23	import { migrateLegacyTasksToNotes } from "./migrations";
24	
25	const APP_ID = process.env.INSTANT_APP_ID!;
26	const ADMIN_TOKEN = process.env.INSTANT_ADMIN_TOKEN!;
27	const PID_FILE = "/tmp/exec-agent.pid";
28	const LESSONS_PATH = resolve(homedir(), "ai/lessons.md");
29	const AGENT_DIR = decodeURIComponent(new URL(".", import.meta.url).pathname);
30	const SYSTEM_PROMPT_PATH = resolve(AGENT_DIR, "system-prompt.md");
31	const TASK_TIMEOUT_MS = 30 * 60 * 1000;
32	const LIVE_OUTPUT_THROTTLE_MS = 2000;
33	const CANCEL_POLL_MS = 3000;
34	const TASK_POLL_MS = 3000;
35	const NOTE_POLL_MS = 3000;
36	const FOLLOW_UP_POLL_MS = 5000;
37	const MAX_CONCURRENT_TASKS = 2;
38	const MAX_TRIAGE_CONCURRENCY = 1;
39	
40	const db: any = init({ appId: APP_ID, adminToken: ADMIN_TOKEN, schema });
41	
42	const runningTasks = new Set<string>();
43	const runningNotes = new Set<string>();
44	const projectLocks = new Set<string>();
45	let dispatchInProgress = false;
46	
47	function acquirePidLock(): boolean {
48	  if (existsSync(PID_FILE)) {
49	    const existingPid = parseInt(readFileSync(PID_FILE, "utf-8").trim(), 10);
50	    try {
51	      process.kill(existingPid, 0);
52	      console.error(`Another agent is running (PID ${existingPid}). Exiting.`);
53	      return false;
54	    } catch {
55	      console.log(`Removing stale PID file (PID ${existingPid}).`);
56	    }
57	  }
58	
59	  writeFileSync(PID_FILE, String(process.pid));
60	  return true;
61	}
62	
63	function releasePidLock() {
64	  try {
65	    if (!existsSync(PID_FILE)) return;
66	    const pid = parseInt(readFileSync(PID_FILE, "utf-8").trim(), 10);
67	    if (pid === process.pid) unlinkSync(PID_FILE);
68	  } catch {}
69	}
70	
71	function truncPath(p: string): string {
72	  const parts = p.split("/");
73	  return parts.length > 3 ? ".../" + parts.slice(-3).join("/") : p;
74	}
75	
76	function truncStr(s: string, max: number): string {
77	  return s.length > max ? s.slice(0, max) + "..." : s;
78	}
79	
80	function formatToolDetail(name: string, input: Record<string, any>): string {
81	  switch (name) {
82	    case "Read":
83	    case "Write":
84	    case "Edit":
85	      return input.file_path ? truncPath(input.file_path) : "";
86	    case "Glob":
87	      return input.pattern || "";
88	    case "Grep":
89	      return input.pattern ? `"${input.pattern}"` : "";
90	    case "Bash":
91	      return input.command ? truncStr(input.command, 80) : "";
92	    case "Agent":
93	      return input.description || input.prompt?.slice(0, 60) || "";
94	    case "WebSearch":
95	      return input.query || "";
96	    case "WebFetch":
97	      return input.url ? truncStr(input.url, 60) : "";
98	    default:
99	      return "";
100	  }
101	}
102	
103	function getProjectSlug(task: any): string | null {
104	  return task.project?.slug || task.projectSlug || null;
105	}
106	
107	function getResumeSessionId(task: any): string | undefined {
108	  return task.project?.sessionId || task.sessionId || undefined;
109	}
110	
111	function hasUnreadUserMessages(task: any): boolean {
112	  const messages = [...(task.messages || [])].sort((a: any, b: any) => a.createdAt - b.createdAt);
113	  const lastSeenId = task.lastSeenMessageId;
114	  const lastSeenIndex = lastSeenId
115	    ? messages.findIndex((message: any) => message.id === lastSeenId)
116	    : -1;
117	  const relevant = lastSeenIndex >= 0 ? messages.slice(lastSeenIndex + 1) : messages;
118	  return relevant.some((message: any) => message.role === "user");
119	}
120	
121	function buildFollowUpPrompt(task: any): string {
122	  const messages = [...(task.messages || [])].sort((a: any, b: any) => a.createdAt - b.createdAt);
123	  const lastSeenId = task.lastSeenMessageId;
124	  let startIndex = 0;
125	
126	  if (lastSeenId) {
127	    const idx = messages.findIndex((message: any) => message.id === lastSeenId);
128	    if (idx >= 0) startIndex = idx + 1;
129	  }
130	
131	  const newMessages = messages
132	    .slice(startIndex)
133	    .filter((message: any) => message.role === "user");
134	
135	  if (newMessages.length === 0) {
136	    return "The user is following up. Check for new context.";
137	  }
138	
139	  return newMessages.map((message: any) => message.content).join("\n\n");
140	}
141	
142	async function ensureProject(slug: string, createdAt: number): Promise<string> {
143	  const existing = await db.query({
144	    projects: {
145	      $: { where: { slug } },
146	    },
147	  } as any);
148	
149	  const project = existing.projects[0] as any;
150	  if (project) return project.id;
151	
152	  const projectId = id();
153	  await db.transact(
154	    db.tx.projects[projectId].update({
155	      slug,
156	      path: getProjectPath(slug),
157	      createdAt,
158	    })
159	  );
160	  return projectId;
161	}
162	
163	async function handleNote(noteId: string) {
164	  const resp = await db.query({
165	    notes: {
166	      $: { where: { id: noteId } },
167	      tasks: {},
168	    },
169	  } as any);
170	
171	  const note = resp.notes[0] as any;
172	  if (!note || note.status !== NOTE_STATUSES.pending) return;
173	  if (!note.transcript?.trim()) {
174	    await db.transact(
175	      db.tx.notes[noteId].update({
176	        status: NOTE_STATUSES.empty,
177	        triagedAt: Date.now(),
178	      })
179	    );
180	    return;
181	  }
182	
183	  await db.transact(
184	    db.tx.notes[noteId].update({
185	      status: NOTE_STATUSES.triaging,
186	      errorMessage: "",
187	    })
188	  );
189	
190	  const dictTerms = await getDictionaryTerms();
191	  const triage = await triageTranscript(note.transcript, dictTerms);
192	  const now = Date.now();
193	
194	  // Re-query the note to get the current summary — summarizeInput may have
195	  // updated it on the client while triage was running (race condition).
196	  const freshResp = await db.query({ notes: { $: { where: { id: noteId } } } } as any);
197	  const currentSummary = (freshResp.notes[0] as any)?.summary;
198	  const hasRealSummary = currentSummary && currentSummary !== SUMMARY_PLACEHOLDER;
199	
200	  if (triage.tasks.length === 0) {
201	    await db.transact(
202	      db.tx.notes[noteId].update({
203	        status: NOTE_STATUSES.empty,
204	        ...(hasRealSummary ? {} : triage.summary ? { summary: triage.summary } : {}),
205	        triageResult: JSON.stringify(triage.rawStructuredOutput ?? []),
206	        triagedAt: now,
207	      })
208	    );
209	    return;
210	  }
211	
212	  const projectIdBySlug = new Map<string, string>();
213	  for (const triagedTask of triage.tasks) {
214	    if (!triagedTask.projectSlug) continue;
215	    if (projectIdBySlug.has(triagedTask.projectSlug)) continue;
216	    const projectId = await ensureProject(triagedTask.projectSlug, now);
217	    projectIdBySlug.set(triagedTask.projectSlug, projectId);
218	  }
219	
220	  const txs: any[] = [
221	    db.tx.notes[noteId].update({
222	      status: NOTE_STATUSES.ready,
223	      ...(hasRealSummary ? {} : triage.summary ? { summary: triage.summary } : {}),
224	      triageResult: JSON.stringify(triage.rawStructuredOutput ?? []),
225	      triagedAt: now,
226	      errorMessage: "",
227	    }),
228	  ];
229	
230	  const taskIds: string[] = [];
231	
232	  for (const [index, triagedTask] of triage.tasks.entries()) {
233	    const taskId = id();
