327	async function reconcileTaskDependencies() {
328	  const resp = await db.query({
329	    tasks: {
330	      $: {
331	        where: {
332	          or: [
333	            { status: TASK_STATUSES.pending },
334	            { status: TASK_STATUSES.blocked },
335	            { status: TASK_STATUSES.running, cancelRequested: true },
336	          ],
337	        },
338	      },
339	      dependencies: { dependsOn: {} },
340	    },
341	  } as any);
342	
343	  for (const task of resp.tasks as any[]) {
344	    const blockers = (task.dependencies || [])
345	      .map((edge: any) => edge.dependsOn)
346	      .filter(Boolean);
347	
348	    if (task.cancelRequested) {
349	      // Don't finalize tasks that are actively running in this process —
350	      // handleTask's abort path will update status. Only reconcile tasks
351	      // that are pending/blocked, or running but not owned by us (stale).
352	      if (task.status === TASK_STATUSES.running && runningTasks.has(task.id)) {
353	        continue;
354	      }
355	      if (task.status !== TASK_STATUSES.cancelled) {
356	        await db.transact(
357	          db.tx.tasks[task.id].update({
358	            status: TASK_STATUSES.cancelled,
359	            blockedReason: "",
360	            errorMessage: "Cancelled by user",
361	            completedAt: Date.now(),
362	            cancelRequested: false,
363	          })
364	        );
365	      }
366	      continue;
367	    }
368	
369	    let desiredStatus = task.status;
370	    let blockedReason = "";
371	
372	    // A dependency is "satisfied" if it has ever completed (completedAt set),
373	    // regardless of its current status. This prevents re-blocking downstream
374	    // tasks when a previously-completed predecessor is cancelled or rerun.
375	    const isSatisfied = (blocker: any) =>
376	      blocker.status === TASK_STATUSES.done || blocker.completedAt;
377	
378	    if (blockers.length === 0) {
379	      desiredStatus = TASK_STATUSES.pending;
380	    } else if (blockers.some((blocker: any) => blocker.status === TASK_STATUSES.failed && !blocker.completedAt)) {
381	      desiredStatus = TASK_STATUSES.blocked;
382	      blockedReason = "dependency_failed";
383	    } else if (blockers.some((blocker: any) => blocker.status === TASK_STATUSES.cancelled && !blocker.completedAt)) {
384	      desiredStatus = TASK_STATUSES.blocked;
385	      blockedReason = "dependency_cancelled";
386	    } else if (blockers.some((blocker: any) => !isSatisfied(blocker))) {
387	      desiredStatus = TASK_STATUSES.blocked;
388	      blockedReason = "waiting_on_dependencies";
389	    } else {
390	      desiredStatus = TASK_STATUSES.pending;
391	    }
392	
393	    if (task.status !== desiredStatus || (task.blockedReason || "") !== blockedReason) {
394	      const update: Record<string, any> = {
395	        status: desiredStatus,
396	        blockedReason,
397	      };
398	      if (desiredStatus === TASK_STATUSES.pending) {
399	        update.errorMessage = "";
400	      }
401	
402	      await db.transact(
403	        db.tx.tasks[task.id].update(update)
404	      );
405	    }
406	  }
407	}
