409	function buildDependencyContext(task: any): string {
410	  const deps = (task.dependencies || [])
411	    .map((edge: any) => edge.dependsOn)
412	    .filter(Boolean);
413	
414	  if (deps.length === 0) return "";
415	
416	  const completedDeps = deps.filter(
417	    (dep: any) => dep.status === TASK_STATUSES.done && dep.result
418	  );
419	
420	  if (completedDeps.length === 0) return "";
421	
422	  const sections = completedDeps.map((dep: any) => {
423	    const title = dep.summary || dep.input;
424	    return `### ${title}\n\n${dep.result}`;
425	  });
426	
427	  return `# Results from prerequisite tasks\n\nThe following tasks were completed before this one. Use their results as context.\n\n${sections.join("\n\n")}`;
428	}
