430	async function handleTask(taskId: string) {
431	  const lessons = existsSync(LESSONS_PATH)
432	    ? readFileSync(LESSONS_PATH, "utf-8")
433	    : "";
434	  const systemPromptMd = existsSync(SYSTEM_PROMPT_PATH)
435	    ? readFileSync(SYSTEM_PROMPT_PATH, "utf-8")
436	    : "";
437	
438	  const resp = await db.query({
439	    tasks: {
440	      $: { where: { id: taskId } },
441	      messages: {},
442	      project: {},
443	      note: {},
444	      dependencies: { dependsOn: {} },
445	    },
446	  } as any);
447	
448	  const task = resp.tasks[0] as any;
449	  if (!task) return;
450	
451	  const resumeSessionId = getResumeSessionId(task);
452	  const isFollowUp = Boolean(resumeSessionId && hasUnreadUserMessages(task));
453	
454	  let prompt: string;
455	  if (isFollowUp) {
456	    prompt = buildFollowUpPrompt(task);
457	  } else {
458	    const depContext = buildDependencyContext(task);
459	    prompt = depContext ? `${depContext}\n\n---\n\n${task.input}` : task.input;
460	  }
461	
462	  await db.transact(
463	    db.tx.tasks[taskId].update({
464	      status: TASK_STATUSES.running,
465	      startedAt: Date.now(),
466	      cancelRequested: false,
467	      blockedReason: "",
468	      errorMessage: "",
469	      liveOutput: "",
470	    })
471	  );
472	
473	  const abortController = new AbortController();
474	  const cancelInterval = setInterval(async () => {
475	    try {
476	      const r = await db.query({ tasks: { $: { where: { id: taskId } } } });
477	      // typed as any to tolerate new reverse-link schema additions
478	      if ((r.tasks[0] as any)?.cancelRequested) {
479	        abortController.abort();
480	      }
481	    } catch {}
482	  }, CANCEL_POLL_MS);
483	
484	  const timeoutHandle = setTimeout(() => {
485	    abortController.abort();
486	  }, TASK_TIMEOUT_MS);
487	
488	  const appendText = [
489	    systemPromptMd,
490	    lessons ? `\n\n# Learned Preferences\n\n${lessons}` : "",
491	  ].filter(Boolean).join("\n\n");
492	
493	  const queryOptions: Record<string, unknown> = {
494	    cwd: getProjectsRoot(),
495	    systemPrompt: {
496	      type: "preset" as const,
497	      preset: "claude_code" as const,
498	      append: appendText,
499	    },
500	    tools: { type: "preset", preset: "claude_code" },
501	    permissionMode: "bypassPermissions",
502	    allowDangerouslySkipPermissions: true,
503	    abortController,
504	  };
505	
506	  if (resumeSessionId) {
507	    queryOptions.resume = resumeSessionId;
508	  }
509	
510	  let activePrompt = prompt;
511	  let q = query({ prompt: activePrompt, options: queryOptions as any });
512	  let sessionId: string | undefined = resumeSessionId;
513	  let lastLiveOutputTime = 0;
514	  const activityItems: {
515	    type: "tool" | "text" | "thinking";
516	    name?: string;
517	    detail?: string;
518	    content?: string;
519	    ts: number;
520	  }[] = [];
521	
522	  function addActivity(item: (typeof activityItems)[0]) {
523	    activityItems.push(item);
524	    if (activityItems.length > 15) {
525	      activityItems.splice(0, activityItems.length - 15);
526	    }
527	  }
528	
529	  async function flushLiveOutput() {
530	    const now = Date.now();
531	    if (now - lastLiveOutputTime < LIVE_OUTPUT_THROTTLE_MS || activityItems.length === 0) {
532	      return;
533	    }
534	
535	    lastLiveOutputTime = now;
536	    await db.transact(
537	      db.tx.tasks[taskId].update({
538	        liveOutput: JSON.stringify(activityItems),
539	      })
540	    );
541	  }
542	
543	  async function runQuery() {
544	    for await (const message of q) {
545	      if (abortController.signal.aborted) break;
546	
547	      if (message.type === "assistant") {
548	        const assistantMsg = message as SDKAssistantMessage;
549	        if (assistantMsg.session_id) sessionId = assistantMsg.session_id;
550	
551	        for (const block of assistantMsg.message.content as any[]) {
552	          if (block.type === "tool_use") {
553	            addActivity({
554	              type: "tool",
555	              name: block.name,
556	              detail: formatToolDetail(block.name, block.input || {}),
557	              ts: Date.now(),
558	            });
559	          } else if (block.type === "thinking" && block.thinking) {
560	            const firstLine = block.thinking.split("\n")[0].trim();
561	            if (firstLine) {
562	              addActivity({
563	                type: "thinking",
564	                content: truncStr(firstLine, 120),
565	                ts: Date.now(),
566	              });
567	            }
568	          } else if (block.type === "text" && block.text) {
569	            const lines = block.text.trim().split("\n");
570	            const lastLine = lines[lines.length - 1]?.trim();
571	            if (lastLine) {
572	              addActivity({
573	                type: "text",
574	                content: truncStr(lastLine, 150),
575	                ts: Date.now(),
576	              });
577	            }
578	          }
579	        }
580	
581	        await flushLiveOutput();
582	      }
583	
584	      if (abortController.signal.aborted) break;
585	
586	      if (message.type === "result") {
587	        const resultMessage = message as SDKResultMessage;
588	        const success = resultMessage.subtype === "success";
589	        const resultText = success ? resultMessage.result || "" : "";
590	        const errors = success ? [] : resultMessage.errors || [];
591	
592	        // If the error is about oversized images, throw so the catch block
593	        // can attempt compaction / fallback instead of marking the task failed.
594	        if (!success && errors.some((e: string) =>
595	          /image.*exceeds.*dimension|dimension.*limit|exceeds.*2000|image.*2000/i.test(e)
596	        )) {
597	          throw new Error(errors.join("\n"));
598	        }
599	
600	        if (resultText) {
601	          await db.transact(
602	            db.tx.messages[id()]
603	              .create({
604	                role: "assistant",
605	                content: resultText,
606	                createdAt: Date.now(),
607	              })
608	              .link({ task: taskId })
609	          );
610	        }
611	
612	        const updated = await db.query({
613	          tasks: { $: { where: { id: taskId } }, messages: {}, project: {} },
614	        } as any);
615	        const updatedTask = updated.tasks[0] as any;
616	        const messages = [...(updatedTask?.messages || [])].sort(
617	          (a: any, b: any) => b.createdAt - a.createdAt
618	        );
619	        const latestMessageId = messages[0]?.id || "";
620	
621	        const taskUpdate = db.tx.tasks[taskId].update({
622	          status: success ? TASK_STATUSES.done : TASK_STATUSES.failed,
623	          result: resultText,
624	          ...(updatedTask?.project ? {} : { sessionId: sessionId || "" }),
625	          liveOutput: "",
626	          blockedReason: "",
627	          errorMessage: success ? "" : (errors.join("\n") || "Unknown error"),
628	          completedAt: Date.now(),
629	          lastSeenMessageId: latestMessageId,
630	          read: false,
631	        });
632	
633	        const txs: any[] = [taskUpdate];
634	        if (updatedTask?.project?.id && sessionId) {
635	          txs.push(db.tx.projects[updatedTask.project.id].update({ sessionId }));
636	        } else if (sessionId) {
637	          txs.push(db.tx.tasks[taskId].update({ sessionId }));
638	        }
639	
640	        await db.transact(txs);
641	      }
642	    }
643	  }
644	
645	  try {
646	    await runQuery();
647	    if (abortController.signal.aborted) {
648	      const err: any = new Error("Aborted");
649	      err.name = "AbortError";
650	      throw err;
651	    }
652	  } catch (error: any) {
653	    // Session has oversized images — try compacting the session to strip them,
654	    // then retry. If /compact itself fails, fall back to a fresh session with
655	    // text-only context from stored messages.
656	    if (
657	      resumeSessionId &&
658	      /image.*exceeds.*dimension|dimension.*limit|exceeds.*2000|image.*2000/i.test(error.message || "")
659	    ) {
660	      console.log(`Task ${taskId}: session has oversized images, attempting /compact`);
661	      try {
662	        const compactQuery = query({
663	          prompt: "/compact",
664	          options: { ...queryOptions, maxTurns: 1 } as any,
665	        });
666	        for await (const msg of compactQuery) {
667	          if ("session_id" in msg && msg.session_id) sessionId = msg.session_id;
668	        }
669	        console.log(`Task ${taskId}: compaction succeeded, retrying with compacted session`);
670	        q = query({ prompt: activePrompt, options: { ...queryOptions, resume: sessionId } as any });
671	        await runQuery();
672	      } catch {
673	        // /compact hit the same image error — fall back to text-only context
674	        console.log(`Task ${taskId}: compaction also failed, retrying with text context`);
675	        const allMessages = [...(task.messages || [])].sort((a: any, b: any) => a.createdAt - b.createdAt);
676	        const thread = allMessages.map((m: any) => `**${m.role}**: ${m.content}`).join("\n\n");
677	        const contextParts = [
678	          `# Original Task\n\n${task.input}`,
679	          thread && `# Conversation History\n\n${thread}`,
680	          task.result && `# Last Result\n\n${task.result}`,
681	          `# New Request\n\n${activePrompt}`,
682	        ].filter(Boolean);
683	        const freshPrompt = contextParts.join("\n\n---\n\n");
684	        delete queryOptions.resume;
685	        sessionId = undefined;
686	        q = query({ prompt: freshPrompt, options: queryOptions as any });
687	        await runQuery();
688	      }
689	    } else if (error.name === "AbortError" || abortController.signal.aborted) {
690	      const r = await db.query({ tasks: { $: { where: { id: taskId } }, messages: {}, project: {} } });
691	      // typed as any to tolerate new reverse-link schema additions
692	      const currentTask = r.tasks[0] as any;
693	      const wasCancelled = currentTask?.cancelRequested;
694	      const messages = [...(currentTask?.messages || [])].sort(
695	        (a: any, b: any) => b.createdAt - a.createdAt
696	      );
697	      const latestMessageId = messages[0]?.id || "";
698	      const txs: any[] = [
699	        db.tx.tasks[taskId].update({
700	          status: wasCancelled ? TASK_STATUSES.cancelled : TASK_STATUSES.failed,
701	          errorMessage: wasCancelled ? "Cancelled by user" : "Task timed out",
702	          liveOutput: "",
703	          blockedReason: "",
704	          completedAt: Date.now(),
705	          lastSeenMessageId: latestMessageId,
706	          cancelRequested: false,
707	          ...(currentTask?.project ? {} : { sessionId: sessionId || "" }),
708	        }),
709	      ];
710	
711	      if (currentTask?.project?.id && sessionId) {
712	        txs.push(db.tx.projects[currentTask.project.id].update({ sessionId }));
713	      }
714	
715	      await db.transact(txs);
716	    } else {
717	      throw error;
718	    }
719	  } finally {
720	    clearInterval(cancelInterval);
721	    clearTimeout(timeoutHandle);
722	  }
723	}
