748	async function dispatchRunnableTasks() {
749	  if (dispatchInProgress) return;
750	  dispatchInProgress = true;
751	
752	  try {
753	    await reconcileTaskDependencies();
754	
755	    while (runningTasks.size < MAX_CONCURRENT_TASKS) {
756	      const resp = await db.query({
757	        tasks: {
758	          $: { where: { status: TASK_STATUSES.pending }, order: { createdAt: "asc" } },
759	          project: {},
760	        },
761	      } as any);
762	
763	      let launched = false;
764	
765	      for (const task of resp.tasks as any[]) {
766	        if (runningTasks.has(task.id)) continue;
767	
768	        const projectSlug = getProjectSlug(task);
769	        if (projectSlug && projectLocks.has(projectSlug)) continue;
770	
771	        if (task.cancelRequested) {
772	          await db.transact(
773	            db.tx.tasks[task.id].update({
774	              status: TASK_STATUSES.cancelled,
775	              errorMessage: "Cancelled by user",
776	              completedAt: Date.now(),
777	              blockedReason: "",
778	            })
779	          );
780	          continue;
781	        }
782	
783	        launchTask(task);
784	        launched = true;
785	        if (runningTasks.size >= MAX_CONCURRENT_TASKS) break;
786	      }
787	
788	      if (!launched) break;
789	    }
790	  } catch (error: any) {
791	    console.error("Task dispatch error:", error.message);
792	  } finally {
793	    dispatchInProgress = false;
794	  }
795	}
