879	  await pollPendingNotes();
880	  await pollForFollowUps();
881	  await dispatchRunnableTasks();
882	
883	  setInterval(() => void pollPendingNotes(), NOTE_POLL_MS);
884	  setInterval(() => void pollForFollowUps(), FOLLOW_UP_POLL_MS);
885	  setInterval(() => void dispatchRunnableTasks(), TASK_POLL_MS);
886	
887	  setInterval(() => {
888	    console.log(
889	      `[heartbeat ${new Date().toISOString()}] tasks=${runningTasks.size} notes=${runningNotes.size} locks=${projectLocks.size}`,
890	    );
891	  }, 5 * 60 * 1000);
892	
893	  console.log("Listening for notes and tasks...");
894	}
895	
896	main().catch((error) => {
897	  console.error("Fatal:", error);
898	  releasePidLock();
899	  process.exit(1);
900	});
